/**
 * World ID v4 Protocol Types
 *
 * Official SDK-based type definitions for frontend-to-backend verification flow.
 * These match the exact structure of @worldcoin/idkit-core responses.
 *
 * @module worldid-types
 */

/**
 * RP Context for IDKit request configuration (frontend).
 * Generated by backend using WorldIdChallengeAdapter.createChallenge().
 */
export interface RpContext {
  /** Relying Party ID (e.g., "rp_abc123...") */
  rp_id: string;
  /** Unique nonce for this proof request (0x-prefixed 64-char hex) */
  nonce: string;
  /** Unix timestamp (seconds) when created */
  created_at: number;
  /** Unix timestamp (seconds) when expires */
  expires_at: number;
  /** ECDSA signature of the RP context (0x-prefixed 130-char hex) */
  signature: string;
}

/**
 * Frontend IDKit request configuration.
 * Passed to IDKit.request() in Telegram Mini App.
 */
export interface FrontendIDKitConfig {
  /** App ID from Developer Portal */
  app_id: `app_${string}`;
  /** Action identifier (stable service/group scope) */
  action: string;
  /** Signed RP context from backend */
  rp_context: RpContext;
  /** Environment */
  environment: 'production' | 'staging';
  /** Reject legacy (v3) proofs (default: false for v4-only) */
  allow_legacy_proofs: boolean;
  /** Signal to bind to proof (e.g., "telegram:12345") */
  signal?: string;
}

/**
 * V4 Credential Response Item (from World App).
 * Matches @worldcoin/idkit-core ResponseItemV4.
 * Nullifiers are 0x-prefixed hex strings per official documentation.
 */
export interface WorldIdV4CredentialResponse {
  /** Credential identifier (e.g., "proof_of_human") */
  identifier: string;
  /** Signal hash (0x-prefixed, present if signal provided in request) */
  signal_hash?: string;
  /** Encoded Groth16 proof (first 4 elements) + Merkle root (5th element) as decimal strings */
  proof: string[];
  /** RP-scoped nullifier (0x-prefixed hex string representing 256-bit integer) */
  nullifier: string;
  /** Credential issuer schema ID (1=proof_of_human, 11=selfie) */
  issuer_schema_id: number;
  /** Minimum expiration timestamp (unix seconds) */
  expires_at_min: number;
}

/**
 * IDKit Result from World App (frontend receives this).
 * Matches @worldcoin/idkit-core IDKitResultV4.
 */
export interface IDKitResult {
  /** Protocol version */
  protocol_version: '4.0';
  /** Nonce from RP context */
  nonce: string;
  /** Action identifier */
  action: string;
  /** Session ID (if session was created) */
  session_id?: `session_${string}`;
  /** Action description (if provided) */
  action_description?: string;
  /** Credential responses */
  responses: WorldIdV4CredentialResponse[];
  /** User presence check completed (if requested) */
  user_presence_completed?: boolean;
  /** Environment */
  environment: string;
}

/**
 * Session Credential Response (from World App for returning users).
 * Contains session_nullifier tuple instead of action nullifier.
 */
export interface WorldIdSessionCredentialResponse {
  /** Credential identifier (e.g., "proof_of_human") */
  identifier: string;
  /** Encoded Groth16 proof (first 4 elements) + Merkle root (5th element) as decimal strings */
  proof: string[];
  /** Session nullifier tuple [nullifier, action] for replay protection */
  session_nullifier: [string, string];
  /** Credential issuer schema ID (1=proof_of_human, 11=selfie) */
  issuer_schema_id: number;
  /** Minimum expiration timestamp (unix seconds) */
  expires_at_min: number;
}

/**
 * IDKit Session Result from World App (for returning users).
 * Returned by IDKit.proveSession() for session-based verification.
 */
export interface IDKitResultSession {
  /** Protocol version */
  protocol_version: '4.0';
  /** Nonce from RP context */
  nonce: string;
  /** Session ID (existing session being verified) */
  session_id: `session_${string}`;
  /** Session credential responses with session_nullifier tuples */
  responses: WorldIdSessionCredentialResponse[];
  /** User presence check completed (if requested) */
  user_presence_completed?: boolean;
  /** Environment */
  environment: string;
}

/**
 * V4 Developer Portal API verification request.
 * Forward complete IDKit result as-is to POST https://developer.world.org/api/v4/verify/{rp_id}
 * Source: https://docs.world.org/world-id/idkit/integrate.md
 * Source: https://docs.world.org/api-reference/developer-portal/verify.md
 */
export type V4VerifyRequest = IDKitResult | IDKitResultSession;

/**
 * V4 Developer Portal API credential verification result.
 * Per-credential result from verification response.
 */
export interface V4VerifyCredentialResult {
  /** Credential identifier (e.g., "proof_of_human") */
  identifier: string;
  /** Verification success for this credential (MUST check this) */
  success: boolean;
  /** Nullifier (0x-prefixed hex string representing 256-bit integer) */
  nullifier: string;
  /** Error code (present on failure) */
  code?: string;
  /** Error detail (present on failure) */
  detail?: string;
}

/**
 * V4 Developer Portal API verification response.
 * Response from POST https://developer.world.org/api/v4/verify/{rp_id}
 * Source: https://docs.world.org/api-reference/developer-portal/verify.md
 */
export interface V4VerifyResponse {
  /** Top-level success (enum true when at least one proof verified) */
  success: true;
  /** Per-credential verification results */
  results: V4VerifyCredentialResult[];
  /** Environment (production/staging/sandbox) */
  environment: string;
}

/**
 * Server-trusted expected verification context.
 * Backend builds this from stored challenge session + requester binding.
 */
export interface ExpectedVerificationContext {
  /** Expected action from stored challenge */
  action: string;
  /** Expected nonce from stored challenge */
  nonce: string;
  /** Expected signal hash from signal binding (0x-prefixed hex) */
  signalHash: string;
  /** Require proof_of_human credential (issuer_schema_id: 1), default true */
  requireProofOfHuman?: boolean;
}

/**
 * Backend verification result (internal).
 */
export interface BackendVerificationResult {
  success: boolean;
  /** Nullifier (0x-prefixed hex string from verified credential) */
  nullifier?: string;
  /** Issuer schema ID */
  issuerSchemaId?: number;
  /** Expiration timestamp */
  expiresAtMin?: number;
  /** Error message (present on failure) */
  error?: string;
}
